'use strict';

// MODULES //

import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import clipUpperIndex from '@stdlib/ndarray-base-clip-upper-index';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-gfind-last-index';


// MAIN //

/**
* Returns the index of the last element in a one-dimensional ndarray which passes a test implemented by a predicate function.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @param {Function} clbk - callback function
* @param {*} [thisArg] - callback execution context
* @returns {integer} index
*
* @example
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
* import vector from '@stdlib/ndarray-vector-ctor';
*
* function isEven( v ) {
*     return v % 2.0 === 0.0;
* }
*
* var x = vector( [ 1.0, 3.0, 4.0, 2.0 ], 'generic' );
*
* var fromIndex = scalar2ndarray( 3, {
*     'dtype': 'generic'
* });
*
* var v = gfindLastIndex( [ x, fromIndex ], isEven );
* // returns 3
*/
function gfindLastIndex( arrays, clbk, thisArg ) {
	var fromIndex;
	var N;
	var x;

	x = arrays[ 0 ];
	fromIndex = ndarraylike2scalar( arrays[ 1 ] );

	N = numelDimension( x, 0 );
	fromIndex = clipUpperIndex( fromIndex, ( fromIndex < 0 ) ? N : N-1 );
	if ( fromIndex < 0 ) {
		return -1;
	}
	return strided( fromIndex+1, getData( x ), getStride( x, 0 ), getOffset( x ), wrapper, null ); // eslint-disable-line max-len

	/**
	* Invokes a provided callback.
	*
	* @private
	* @param {*} value - current array element
	* @param {NonNegativeInteger} aidx - current array element index
	* @param {NonNegativeInteger} sidx - current strided array element index
	* @param {Collection} arr - input array
	* @returns {*} result
	*/
	function wrapper( value, aidx ) {
		return clbk.call( thisArg, value, fromIndex - aidx, x );
	}
}


// EXPORTS //

export default gfindLastIndex;
